    appendProgress(runDir, `RESUME turn ${state.turns + 1}`);
    unsubscribeEvents = client.onSessionEvent(onSessionEvent);
    wallClock = setTimeout(() => void finish("max_seconds"), opts.maxSeconds * 1000);
